CREATE TABLE ownerships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),starts_on date NOT NULL,ends_on date,share_basis_points integer NOT NULL CHECK(share_basis_points BETWEEN 1 AND 10000),FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id),CHECK(ends_on IS NULL OR ends_on>=starts_on));
CREATE TABLE occupancies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES users(id),starts_on date NOT NULL,ends_on date,FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id),CHECK(ends_on IS NULL OR ends_on>=starts_on));
CREATE TABLE leases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL,renter_id uuid NOT NULL REFERENCES users(id),starts_on date NOT NULL,ends_on date NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency text NOT NULL CHECK(currency IN ('AMD','RUB','USD')),created_by uuid NOT NULL REFERENCES users(id),FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id),CHECK(ends_on>=starts_on));
CREATE TABLE handover_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL UNIQUE,status text NOT NULL DEFAULT 'inspection' CHECK(status IN ('inspection','ready','operational')),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id));
CREATE TABLE inspections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),handover_id uuid NOT NULL REFERENCES handover_cases(id),scheduled_at timestamptz NOT NULL,checklist jsonb NOT NULL,report text NOT NULL DEFAULT '',completed_at timestamptz,completed_by uuid REFERENCES users(id));
CREATE TABLE warranties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,unit_id uuid NOT NULL,description text NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL,FOREIGN KEY(unit_id,organization_id) REFERENCES units(id,organization_id),CHECK(ends_on>=starts_on));
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL,building_id uuid NOT NULL,unit_id uuid,title text NOT NULL,visibility text NOT NULL CHECK(visibility IN ('staff','residents','unit_owner')),storage_key text NOT NULL UNIQUE,media_type text NOT NULL,uploaded_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(building_id,organization_id) REFERENCES buildings(id,organization_id),FOREIGN KEY(unit_id,building_id,organization_id) REFERENCES units(id,building_id,organization_id),CHECK(visibility<>'unit_owner' OR unit_id IS NOT NULL));
CREATE TABLE subscription_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,amount_minor bigint NOT NULL CHECK(amount_minor>=0),currency text NOT NULL CHECK(currency IN ('AMD','RUB','USD')),building_limit integer NOT NULL CHECK(building_limit>0));
CREATE TABLE subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),plan_id uuid NOT NULL REFERENCES subscription_plans(id),starts_on date NOT NULL,ends_on date NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused')),created_by uuid NOT NULL REFERENCES users(id),CHECK(ends_on>=starts_on));
CREATE TABLE support_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),created_by uuid NOT NULL REFERENCES users(id),assigned_to uuid REFERENCES users(id),subject text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','resolved')),reply text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE onboarding_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),assigned_to uuid NOT NULL REFERENCES users(id),title text NOT NULL,due_on date NOT NULL,completed_at timestamptz,UNIQUE(organization_id,title));
INSERT INTO permissions(key) VALUES('documents.read'),('documents.manage'),('leases.read'),('leases.manage'),('handover.read'),('handover.manage'),('subscriptions.manage'),('support.cases'),('support.cases.create') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_key,permission_key) VALUES('platform_admin','subscriptions.manage'),('support','support.cases'),('org_admin','support.cases.create'),('org_admin','documents.read'),('org_admin','documents.manage'),('manager','documents.read'),('manager','documents.manage'),('manager','leases.read'),('manager','leases.manage'),('portfolio_owner','leases.read'),('unit_owner','documents.read'),('renter','documents.read'),('family','documents.read'),('developer','handover.read'),('developer','handover.manage') ON CONFLICT DO NOTHING;
INSERT INTO module_entitlements(organization_id,module) SELECT id,'documents' FROM organizations ON CONFLICT DO NOTHING;
